import sys, json; 
def respond(id, result): print(json.dumps({'jsonrpc': '2.0', 'id': id, 'result': result}), flush=True)
for line in sys.stdin:
  req = json.loads(line)
  if req['method'] == 'initialize': respond(req['id'], {'protocolVersion': '2024-11-05', 'capabilities': {}, 'serverInfo': {'name': 'test'}})
  elif req['method'] == 'notifications/initialized': pass
  elif req['method'] == 'tools/list': respond(req['id'], {'tools': [{'name': 'execute', 'inputSchema': {'type': 'object'}}]})
  elif req['method'] == 'tools/call': respond(req['id'], {'content': [{'type': 'text', 'text': 'Success'}]})
